# -*- coding: utf-8 -*-
"""The comprehensive report in simple Hebrew: reports/Nofit_LRT_Extension_Comprehensive_Report_HE.docx
Same structure and the same numbers as the English report (tools/build_comprehensive_report.py), shorter and in plain language;
the charts are the English ones (Output/figures/comprehensive/, Output/figures/alternatives/). Right-to-left paragraphs and tables.
Run after tools/build_comprehensive_report.py:  python3 tools/build_comprehensive_report_he.py"""
import os
import numpy as np, pandas as pd
from docx import Document
from docx.shared import Pt, Cm
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.section import WD_ORIENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
while not os.path.exists('METHODOLOGY.md') and os.getcwd() != '/': os.chdir('..')
# the data, the helpers and the reference-case numbers of the English builder (everything before its Word report), so both reports read the same files
_src = open('tools/build_comprehensive_report.py', encoding='utf-8').read()
_head, _rest = _src.split('# ======================= 0 =======================')
_head = _head.replace("doc = Document()", "doc = Document()  # the English builder's document object; not saved here")
exec(_head)   # noqa: defines summary, tabs, PHF, phf, loads, srow, ext_row, through_table, market_summary, market_tables, cross_hamifrats, busiest, ref, refE, refP, ref_unp, ref_slow, RANGE_LO/HI, mk_ref, SCEN, SCEN_LAB, REF, REG, OUT, CFIG, FIG, fA, fP, ref_brt_shift, ref_bus_shift

# ---------------- right-to-left Word helpers ----------------
doc = Document()
st = doc.styles['Normal']; st.font.name = 'Arial'; st.font.size = Pt(11); st.element.rPr.rFonts.set(qn('w:cs'), 'Arial')
for sec in doc.sections: sec.left_margin = sec.right_margin = Cm(2)
def rtl(p, size=None, bold=None, italic=None):
    pPr = p._p.get_or_add_pPr(); b = OxmlElement('w:bidi'); b.set(qn('w:val'), '1'); pPr.append(b); p.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    for r in p.runs:
        rPr = r._r.get_or_add_rPr(); e = OxmlElement('w:rtl'); e.set(qn('w:val'), '1'); rPr.append(e)
        fonts = rPr.find(qn('w:rFonts'))
        if fonts is None: fonts = OxmlElement('w:rFonts'); rPr.insert(0, fonts)
        fonts.set(qn('w:cs'), 'Arial'); fonts.set(qn('w:ascii'), 'Arial'); fonts.set(qn('w:hAnsi'), 'Arial')
        if size: r.font.size = Pt(size)
        if bold is not None: r.font.bold = bold
        if italic is not None: r.font.italic = italic
    return p
def P(text, size=None, bold=None, italic=None): return rtl(doc.add_paragraph(text), size, bold, italic)
def B(text): return rtl(doc.add_paragraph(text, style='List Bullet'))
def H(text, lvl=1): return rtl(doc.add_heading(text, lvl))
def CAP(text): return P(text, size=9, italic=True)
def table(df, fmt=None, font=9):
    fmt = fmt or {}
    t = doc.add_table(rows=1, cols=len(df.columns)); t.style = 'Light Grid Accent 1'
    tblPr = t._tbl.tblPr; bv = OxmlElement('w:bidiVisual'); bv.set(qn('w:val'), '1'); tblPr.append(bv)
    for j, c in enumerate(df.columns):
        cell = t.rows[0].cells[j]; cell.text = str(c)
        for par in cell.paragraphs: rtl(par, font, True)
    for _, r in df.iterrows():
        cells = t.add_row().cells
        for j, (c, v) in enumerate(r.items()):
            f = fmt.get(c, '{:,.0f}')
            cells[j].text = (f.format(v) if isinstance(v, (float, int, np.floating, np.integer)) and not isinstance(v, bool) and np.isfinite(v) else ('' if isinstance(v, float) else str(v)))
            for par in cells[j].paragraphs: rtl(par, font)
    return t
def fig(path, width=16, caption=None):
    if os.path.exists(path):
        doc.add_picture(path, width=Cm(width)); doc.paragraphs[-1].alignment = WD_ALIGN_PARAGRAPH.CENTER
        if caption: CAP(caption)
    else: P(f'[חסר איור: {path}]')
def landscape():
    sec = doc.add_section(); sec.orientation = WD_ORIENT.LANDSCAPE; sec.page_width, sec.page_height = max(sec.page_width, sec.page_height), min(sec.page_width, sec.page_height); sec.left_margin = sec.right_margin = Cm(1.5)
def portrait():
    sec = doc.add_section(); sec.orientation = WD_ORIENT.PORTRAIT; sec.page_width, sec.page_height = min(sec.page_width, sec.page_height), max(sec.page_width, sec.page_height); sec.left_margin = sec.right_margin = Cm(2)
def n(x): return f'{x:,.0f}'
def pct(x, d=0): return f'{x:.{d}f} %'
SC_HE = {'2022': '2022', 'BU_2040': '2040 רגיל', 'BU_2050': '2050 רגיל', 'HS_2040': '2040 גבוה', 'HS_2050': '2050 גבוה'}
LAB_HE = {'2022': '2022', '2040 BU': '2040 רגיל', '2050 BU': '2050 רגיל', '2040 HS': '2040 גבוה', '2050 HS': '2050 גבוה'}
ext_use = ref['LRT trips using the extension (at least one segment S01–S24)']; ext_both = ref['LRT trips on the extension stations (both ends on S01–S24)']
cross = cross_hamifrats('AM', REF); peak_line = busiest('AM', REF, peak=True); peak_ext = busiest('AM', REF, ext_only_segments=True, peak=True)

# ======================= title =======================
rtl(doc.add_heading('הרכבת הקלה נופית — הארכת הקו לחיפה וטירת כרמל: בדיקת הביקוש', 0))
P('דוח מסכם בשפה פשוטה: מה רצינו לדעת, איך בנינו את "המודל" ומאילו נתונים, איך כיילנו ובדקנו את שנת הבסיס, מה התוצאות לשנים 2040 ו-2050, ומה המסקנות. '
  'זהו תרגום מקוצר של הדוח המלא באנגלית (Nofit_LRT_Extension_Comprehensive_Report.docx), עם אותם מספרים בדיוק; האיורים לקוחים מהדוח האנגלי וכיתוביהם באנגלית. הופק ב-5 באוקטובר 2026.')

