    ['השווקים הגדולים (בוקר, 3 שעות)', f'טירת כרמל ↔ חיפה {n(mk_ref.iloc[1]["LRT trips (3 h)"])} ({pct(mk_ref.iloc[1]["share of all LRT trips"])}); בתוך חיפה {n(mk_ref.iloc[0]["LRT trips (3 h)"])} ({pct(mk_ref.iloc[0]["share of all LRT trips"])}); הקריות ↔ חיפה (בהזנה) {n(mk_ref.iloc[2]["LRT trips (3 h)"])} ({pct(mk_ref.iloc[2]["share of all LRT trips"])}); הקו הראשי ↔ חיפה {n(mk_ref.iloc[3]["LRT trips (3 h)"])} ({pct(mk_ref.iloc[3]["share of all LRT trips"])})'],
    ['הארכה בלי עדיפות בצמתים (ברמת הרחוב)', f'{n(ref_unp["LRT"])} ({(ref_unp["LRT"] / ref["LRT"] - 1) * 100:+.0f} %)'],
